    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Edge cases: empty quoted values ---

    #[test]
    fn empty_double_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn empty_single_quoted_value() {
        let vars = EnvFileParser::parse("KEY=''").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    // --- Edge cases: mismatched quotes ---

    #[test]
    fn mismatched_quotes_double_then_single() {
        let vars = EnvFileParser::parse(r#"KEY="value'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_single_then_double() {
        let vars = EnvFileParser::parse(r#"KEY='value""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"'value""#.to_string()));
    }

    // --- Edge cases: single quote character as entire value ---

    #[test]
    fn single_double_quote_as_value() {
        let vars = EnvFileParser::parse(r#"KEY=""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"""#.to_string()));
    }

    #[test]
    fn single_single_quote_as_value() {
        let vars = EnvFileParser::parse("KEY='").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    // --- Edge cases: triple quotes ---

    #[test]
    fn triple_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY=""""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"""#.to_string()));
    }

    // --- Edge cases: backslashes and escape sequences ---

    #[test]
    fn backslash_escaped_quotes_in_double_quoted_value() {
        // Parser does not interpret escape sequences; backslashes are literal
        let vars = EnvFileParser::parse(r#"KEY="hello \"world\"""#).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"hello \"world\""#.to_string())
        );
    }

    #[test]
    fn backslash_in_unquoted_value() {
        let vars = EnvFileParser::parse(r"KEY=path\to\dir").unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\to\dir".to_string()));
    }

    #[test]
    fn backslash_in_double_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="path\to\dir""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\to\dir".to_string()));
    }

    #[test]
    fn newline_escape_sequence_preserved_literally() {
        // \n stays as literal backslash-n, not a newline character
        let vars = EnvFileParser::parse(r#"KEY="line1\nline2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
    }

    #[test]
    fn tab_escape_sequence_preserved_literally() {
        let vars = EnvFileParser::parse(r#"KEY="col1\tcol2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"col1\tcol2".to_string()));
    }

    #[test]
    fn trailing_backslash_in_value() {
        let vars = EnvFileParser::parse(r"KEY=value\").unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"value\".to_string()));
    }

    #[test]
    fn consecutive_backslashes() {
        let vars = EnvFileParser::parse(r"KEY=\\\\").unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"\\\\".to_string()));
    }

    // --- Edge cases: nested quotes ---

    #[test]
    fn single_quotes_inside_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="it's a value""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a value".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let vars = EnvFileParser::parse(r#"KEY='say "hello"'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
    }

    #[test]
    fn quotes_in_middle_of_unquoted_value() {
        let vars = EnvFileParser::parse(r#"KEY=mid"dle"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"mid"dle"#.to_string()));
    }

    // --- Edge cases: whitespace handling ---

    #[test]
    fn whitespace_preserved_inside_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="  spaced  ""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn whitespace_preserved_inside_single_quotes() {
        let vars = EnvFileParser::parse("KEY='  spaced  '").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn leading_whitespace_before_key_is_trimmed() {
        let vars = EnvFileParser::parse("  KEY=value").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn only_whitespace_value_becomes_empty() {
        let vars = EnvFileParser::parse("KEY=   ").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    // --- Edge cases: inline comments ---

    #[test]
    fn inline_comment_not_stripped_from_value() {
        // Parser does not strip inline comments
        let vars = EnvFileParser::parse("KEY=value # comment").unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # comment".to_string())
        );
    }

    #[test]
    fn hash_inside_quoted_value() {
        let vars =
            EnvFileParser::parse(r#"KEY="value # not a comment""#).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    // --- Edge cases: export prefix ---

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // Parser does not strip export prefix
        let vars = EnvFileParser::parse("export KEY=value").unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
    }

    // --- Edge cases: special characters ---

    #[test]
    fn unicode_in_value() {
        let vars = EnvFileParser::parse("KEY=café").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"café".to_string()));
    }

    #[test]
    fn unicode_in_key() {
        let vars = EnvFileParser::parse("КЛЮЧ=значение").unwrap();
        assert_eq!(vars.get("КЛЮЧ"), Some(&"значение".to_string()));
    }

    #[test]
    fn multiple_equals_in_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="a=b=c""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c".to_string()));
    }

    // --- Edge cases: duplicate keys and ordering ---

    #[test]
    fn duplicate_keys_last_value_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    // --- Edge cases: empty and whitespace-only input ---

    #[test]
    fn empty_input_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
