        assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
    }

    #[test]
    fn quotes_in_middle_of_unquoted_value() {
        let vars = EnvFileParser::parse(r#"KEY=mid"dle"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"mid"dle"#.to_string()));
    }

    // --- Edge cases: whitespace handling ---

    #[test]
    fn whitespace_preserved_inside_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="  spaced  ""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn whitespace_preserved_inside_single_quotes() {
        let vars = EnvFileParser::parse("KEY='  spaced  '").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn leading_whitespace_before_key_is_trimmed() {
        let vars = EnvFileParser::parse("  KEY=value").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn only_whitespace_value_becomes_empty() {
        let vars = EnvFileParser::parse("KEY=   ").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

